package io.github.weimanmk.easygot;

import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.util.*;

public class CoreTest {
    private JSONObject choice(String type)throws Exception{return new JSONObject("{\"id\":\"q\",\"type\":\""+type+"\",\"stem\":\"选出正确选项\",\"maxScore\":5,\"options\":[{\"id\":\"A\",\"text\":\"甲\"},{\"id\":\"B\",\"text\":\"乙\"}],\"answer\":[\"A\",\"B\"]}");}
    @Test public void multipleChoiceIsOrderIndependentButRejectsDuplicates()throws Exception{JSONObject q=choice("multiple");Domain.question(q);assertEquals(5,Domain.objectiveScore(q,new JSONArray("[\"B\",\"A\"]")),0);assertEquals(0,Domain.objectiveScore(q,new JSONArray("[\"A\"]")),0);assertEquals(0,Domain.objectiveScore(q,new JSONArray("[\"A\",\"B\",\"B\"]")),0);}
    @Test public void malformedChoiceCannotEnterBank()throws Exception{JSONObject q=choice("single");assertThrows(JSONException.class,()->Domain.question(q));q.put("answer",new JSONArray().put("C"));assertThrows(JSONException.class,()->Domain.question(q));}
    @Test public void booleanRequiresActualBoolean()throws Exception{JSONObject q=new JSONObject("{\"id\":\"b\",\"type\":\"boolean\",\"stem\":\"判断\",\"maxScore\":2,\"answer\":true}");assertEquals(2,Domain.objectiveScore(q,true),0);assertEquals(0,Domain.objectiveScore(q,"true"),0);q.put("answer","true");assertThrows(JSONException.class,()->Domain.question(q));}
    @Test public void invalidAiGradeCannotBeSaved()throws Exception{JSONObject g=new JSONObject("{\"score\":11,\"feedback\":\"x\",\"explanation\":\"y\"}");assertThrows(JSONException.class,()->Domain.checkedGrade(g,10));g.put("score",4.5);assertEquals(4.5,Domain.checkedGrade(g,10).getDouble("score"),0);}
    private JSONObject revision(String version,String... parents)throws Exception{return new JSONObject().put("version",version).put("entityId","note-1").put("kind","note").put("parents",new JSONArray(parents)).put("payload",new JSONObject().put("id","note-1"));}
    @Test public void concurrentEditsRemainUntilExplicitMerge()throws Exception{JSONObject a=revision("a"),b=revision("b","a"),c=revision("c","a");List<JSONObject> records=new ArrayList<>(List.of(c,a,b));RevisionGraph.validate(records);assertEquals(2,RevisionGraph.heads(records).size());records.add(revision("merge","b","c"));RevisionGraph.validate(records);assertEquals("merge",RevisionGraph.heads(records).get(0).getString("version"));}
    @Test public void missingParentsCrossRecordLinksAndCyclesAreRejected()throws Exception{assertThrows(JSONException.class,()->RevisionGraph.validate(List.of(revision("b","missing"))));assertThrows(JSONException.class,()->RevisionGraph.validate(List.of(revision("a","b"),revision("b","a"))));JSONObject a=revision("a"),b=revision("b","a").put("entityId","other");assertThrows(JSONException.class,()->RevisionGraph.validate(List.of(a,b)));}
    @Test public void deepSeekUsesOfficialFieldsAndUnicodeLength()throws Exception{JSONObject r=DeepSeekSearch.searchRequest("网络协议",5,true);assertEquals(5,r.getInt("count"));assertTrue(r.getBoolean("need_content"));assertFalse(r.has("max_results"));assertThrows(JSONException.class,()->DeepSeekSearch.searchRequest(" ",5,true));assertThrows(JSONException.class,()->DeepSeekSearch.searchRequest("题",51,true));assertThrows(JSONException.class,()->DeepSeekSearch.searchRequest("题".repeat(129),5,true));assertNotNull(DeepSeekSearch.searchRequest("😀".repeat(128),5,true));}
    @Test public void weightsAllocateExactCountAndEnforceBlueprint()throws Exception{JSONObject spec=new JSONObject("{\"count\":5,\"difficulty\":3,\"typeCounts\":{\"single\":5},\"weights\":{\"甲\":3,\"乙\":2}}");Blueprint.validate(spec);assertEquals(3,spec.getJSONObject("knowledgePointCounts").getInt("甲"));JSONArray qs=new JSONArray();for(int i=0;i<5;i++)qs.put(new JSONObject().put("type","single").put("difficulty",3).put("knowledgePoints",new JSONArray().put(i<3?"甲":"乙")));Blueprint.verify(spec,qs);qs.getJSONObject(0).put("type","short");assertThrows(JSONException.class,()->Blueprint.verify(spec,qs));}
}
